def amicable_numbers_sum(n):
    def sum_proper_divisors(x):
        if x <= 1:
            return 0
        total = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                total += i
                pair = x // i
                if pair != i:
                    total += pair
            i += 1
        return total

    total = 0
    for num in range(1, n + 1):
        s = sum_proper_divisors(num)
        if s != num and sum_proper_divisors(s) == num:
            total += num
    return total
