def max_occurrences(lst):
    if not lst:
        return None
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
    best_item = lst[0]
    best_count = counts[lst[0]]
    for item in lst:
        if counts[item] > best_count:
            best_count = counts[item]
            best_item = item
    return best_item
