import math

def perfect_squares(a, b):
    lo, hi = min(a, b), max(a, b)
    result = []
    if hi < 0:
        return result
    # Find the smallest integer n such that n*n >= lo
    if lo <= 0:
        start = 0
    else:
        start = math.isqrt(lo)
        if start * start < lo:
            start += 1
    n = start
    while n * n <= hi:
        result.append(n * n)
        n += 1
    return result
