def find_kth(arr1, arr2, k):
    """
    Find the kth element (1-indexed) in the merged sorted order
    of two sorted arrays.
    """
    # Ensure arr1 is the shorter array
    if len(arr1) > len(arr2):
        return find_kth(arr2, arr1, k)

    # Base cases
    if not arr1:
        return arr2[k - 1]
    if k == 1:
        return min(arr1[0], arr2[0])

    # Compare the elements at position k//2 in each array
    i = min(len(arr1), k // 2)
    j = min(len(arr2), k // 2)

    if arr1[i - 1] > arr2[j - 1]:
        # Discard the first j elements of arr2
        return find_kth(arr1, arr2[j:], k - j)
    else:
        # Discard the first i elements of arr1
        return find_kth(arr1[i:], arr2, k - i)
